-- Cloud synchronization schema and immutable documentary catalog.

      CREATE TABLE IF NOT EXISTS sync_catalog_revisions (
        revision TEXT PRIMARY KEY,
        schema_version TEXT NOT NULL,
        sources JSONB NOT NULL
      );
      CREATE TABLE IF NOT EXISTS sync_environment_profiles (
        revision TEXT NOT NULL REFERENCES sync_catalog_revisions (revision),
        scenario_id TEXT NOT NULL,
        definition JSONB NOT NULL,
        PRIMARY KEY (revision, scenario_id)
      );
      CREATE TABLE IF NOT EXISTS synced_measurements (
        measurement_id TEXT PRIMARY KEY,
        mission_id TEXT NOT NULL,
        scenario_id TEXT NOT NULL,
        revision TEXT NOT NULL,
        payload JSONB NOT NULL,
        received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
        FOREIGN KEY (revision, scenario_id) REFERENCES sync_environment_profiles (revision, scenario_id)
      );
    
ALTER TABLE public.sync_catalog_revisions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.sync_catalog_revisions FROM anon, authenticated;
ALTER TABLE public.sync_environment_profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.sync_environment_profiles FROM anon, authenticated;
ALTER TABLE public.synced_measurements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.synced_measurements FROM anon, authenticated;
INSERT INTO public.sync_catalog_revisions (revision,schema_version,sources) VALUES ('50e2ad62a7dc6a2f32aa4f20b05361fff0613f2268e0bf7efce089e47b1e352b','1.1.0','{"nasa_moon_facts":{"name":"Moon Fact Sheet","organization":"NASA NSSDC","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html"},"nasa_mars_facts":{"name":"Mars Fact Sheet","organization":"NASA NSSDC","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html"},"artemis1_2024":{"name":"Space radiation measurements during the Artemis I lunar mission","organization":"George et al., Nature (2024)","url":"https://doi.org/10.1038/s41586-024-07927-7"},"lnd_2020":{"name":"First measurements of the radiation dose on the lunar surface","organization":"Zhang et al., Science Advances (2020)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7518862/"},"nasa_mars_rad":{"name":"Radiation Measurements on Mars (Curiosity RAD)","organization":"NASA/JPL-Caltech/SwRI","url":"https://science.nasa.gov/resource/radiation-measurements-on-mars/"},"nasa_radlab":{"name":"RadLab Data API","organization":"NASA OSDR","url":"https://visualization.osdr.nasa.gov/radlab/gui/data-api/"},"nasa_eda":{"name":"Environmental Data App","organization":"NASA OSDR","url":"https://visualization.osdr.nasa.gov/eda/"},"nasa_meda":{"name":"Perseverance MEDA","organization":"NASA PDS","url":"https://pdsatmospheres.nmsu.edu/data_and_services/atmospheres_data/PERSEVERANCE/meda.html"},"nasa_diviner":{"name":"LRO Diviner Calibrated Data","organization":"NASA PDS","url":"https://pds-geosciences.wustl.edu/missions/lro/diviner.htm"},"nasa_crater":{"name":"LRO CRaTER","organization":"NASA PDS","url":"https://pds.nasa.gov/ds-view/pds/viewBundle.jsp?identifier=urn%3Anasa%3Apds%3Alro-crater&version=1.6"},"nasa_msl_rad":{"name":"MSL RAD Level 2 Observations","organization":"NASA Open Data / PDS","url":"https://data.nasa.gov/dataset/mars-science-laboratory-msl-radiation-assessment-detector-rad-level-2-observation-dosimetr"},"nasa_donki":{"name":"DONKI API","organization":"NASA CCMC","url":"https://api.nasa.gov/"},"nasa_oltaris":{"name":"OLTARIS radiation transport modeling","organization":"NASA","url":"https://oltaris.larc.nasa.gov/"},"nasa_celestial_dust_risk":{"name":"Risk of Adverse In-Mission Health and Performance Effects and Long-Term Health Effects Due to Celestial Dust Exposure","organization":"NASA Human Research Program","url":"https://www.nasa.gov/directorates/esdmd/hhp/risk-of-adverse-health-performance-effects-of-celestial-dust-exposure/"},"nasa_lunar_regolith":{"name":"What Hazards Are Caused by Lunar Regolith?","organization":"NASA Science","url":"https://science.nasa.gov/biological-physical/what-hazards-are-caused-by-lunar-regolith/"}}'::jsonb);
INSERT INTO public.sync_environment_profiles (revision,scenario_id,definition) VALUES ('50e2ad62a7dc6a2f32aa4f20b05361fff0613f2268e0bf7efce089e47b1e352b','deep_space_transit','{"id":"deep_space_transit","label":"Tránsito interplanetario en nave (referencia: Orion Artemis I)","setting":"interior_de_nave_no_es_superficie_exterior","conditions":[{"metric":"effective_gravity","scope":"cabin","value":null,"unit":"m/s2","reason":"La microgravedad depende de la trayectoria y de las aceleraciones de la nave; no hay una medida universal para todos los tránsitos"},{"metric":"radiation_gcr_equivalent_rate_range","scope":"instrument","value":{"min":0.96,"max":1.24},"unit":"mSv/day","sourceId":"artemis1_2024","evidenceType":"published_measured_range","context":"Interior de Orion; detectores HERA; componente GCR; no implica dosis personal ni eventos solares"},{"metric":"radiation_mission_total_equivalent_range","scope":"instrument","value":{"min":26.7,"max":35.4},"unit":"mSv","sourceId":"artemis1_2024","evidenceType":"published_measured_range","context":"Dosis equivalentes acumuladas en posiciones instrumentadas durante Artemis I; misión sin tripulación"},{"metric":"temperature_c","scope":"cabin","value":null,"unit":"°C","reason":"No existe una temperatura ambiental universal del interior de naves interplanetarias"},{"metric":"co2_ppm","scope":"cabin","value":null,"unit":"ppm","reason":"Depende del control ambiental de la nave y de telemetría específica"},{"metric":"cabin_pressure_pa","scope":"cabin","value":null,"unit":"Pa","reason":"Depende del vehículo y de telemetría específica"}]}'::jsonb);
INSERT INTO public.sync_environment_profiles (revision,scenario_id,definition) VALUES ('50e2ad62a7dc6a2f32aa4f20b05361fff0613f2268e0bf7efce089e47b1e352b','iss_leo','{"id":"iss_leo","label":"Estación Espacial Internacional, órbita terrestre baja","setting":"interior_iss_y_referencias_instrumentales","conditions":[{"metric":"effective_gravity","scope":"cabin","value":null,"unit":"m/s2","reason":"Microgravedad orbital; no asignar gravedad superficial terrestre como gravedad efectiva a bordo"},{"metric":"radiation_equivalent_rate_comparison","scope":"instrument","value":731,"unit":"µSv/day","sourceId":"lnd_2020","evidenceType":"measured_period_average_reported_in_peer_reviewed_article","context":"ISS DOSTEL DOSIS 3D; mismo período de comparación del experimento lunar, NO valor constante para la ISS"},{"metric":"radiation_gcr_component_comparison","scope":"instrument","value":523,"unit":"µSv/day","sourceId":"lnd_2020","evidenceType":"measured_period_average_reported_in_peer_reviewed_article","context":"Componente GCR de la comparación ISS; el valor total también incluye anomalía del Atlántico Sur"},{"metric":"cabin_temperature_c","scope":"cabin","value":null,"unit":"°C","reason":"Disponible por misión en EDA; no se descargó una serie verificable"},{"metric":"cabin_relative_humidity_pct","scope":"cabin","value":null,"unit":"%","reason":"Disponible por misión en EDA; no se descargó una serie verificable"},{"metric":"cabin_co2_ppm","scope":"cabin","value":null,"unit":"ppm","reason":"Disponible por misión en EDA; no se descargó una serie verificable"},{"metric":"cabin_pressure_pa","scope":"cabin","value":null,"unit":"Pa","reason":"No verificado para un instante y módulo concretos"}]}'::jsonb);
INSERT INTO public.sync_environment_profiles (revision,scenario_id,definition) VALUES ('50e2ad62a7dc6a2f32aa4f20b05361fff0613f2268e0bf7efce089e47b1e352b','moon_surface','{"id":"moon_surface","label":"Superficie lunar exterior (EVA con traje)","setting":"superficie_exterior_lunar_con_traje","conditions":[{"metric":"gravity_surface","scope":"exterior","value":1.62,"unit":"m/s2","sourceId":"nasa_moon_facts","evidenceType":"planetary_reference"},{"metric":"gravity_relative_to_earth","scope":"exterior","value":0.165,"unit":"g_earth","sourceId":"nasa_moon_facts","evidenceType":"planetary_reference"},{"metric":"exterior_surface_temperature_equator_range","scope":"exterior","value":{"min":95,"max":390},"unit":"K","sourceId":"nasa_moon_facts","evidenceType":"published_reference_range","context":"Rango diurno de temperatura ecuatorial de la superficie, NO del aire ni del interior de una base"},{"metric":"exosphere_surface_pressure_night","scope":"exterior","value":3e-15,"unit":"bar","sourceId":"nasa_moon_facts","evidenceType":"published_reference","context":"Exosfera nocturna; depende de condiciones y ubicación; no es atmósfera respirable"},{"metric":"radiation_total_absorbed_dose_rate","scope":"instrument","value":13.2,"unit":"µGy/hour","sourceId":"lnd_2020","evidenceType":"measured_study_average","context":"Chang’e-4 LND, absorbida en silicio, instrumento en módulo de aterrizaje; NO dosis humana dentro de hábitat","uncertainty":{"plusMinus":1,"unit":"µGy/hour"}},{"metric":"radiation_neutral_absorbed_dose_rate","scope":"instrument","value":3.1,"unit":"µGy/hour","sourceId":"lnd_2020","evidenceType":"measured_study_average","context":"Partículas neutras en detector LND; no sumar de nuevo al total","uncertainty":{"plusMinus":0.5,"unit":"µGy/hour"}},{"metric":"radiation_equivalent_dose_rate","scope":"instrument","value":1369,"unit":"µSv/day","sourceId":"lnd_2020","evidenceType":"measured_study_average","context":"Promedio reportado en superficie lunar; no dosis en una base protegida"}]}'::jsonb);
INSERT INTO public.sync_environment_profiles (revision,scenario_id,definition) VALUES ('50e2ad62a7dc6a2f32aa4f20b05361fff0613f2268e0bf7efce089e47b1e352b','mars_surface','{"id":"mars_surface","label":"Superficie marciana exterior (EVA con traje)","setting":"superficie_exterior_marciana_con_traje","conditions":[{"metric":"gravity_surface_mean","scope":"exterior","value":3.73,"unit":"m/s2","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference"},{"metric":"gravity_relative_to_earth","scope":"exterior","value":0.38,"unit":"g_earth","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference"},{"metric":"exterior_surface_pressure_mean_radius","scope":"exterior","value":6.36,"unit":"mbar","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference","context":"Valor de referencia a radio medio; NO lectura instantánea en Jezero"},{"metric":"exterior_surface_pressure_seasonal_reference_range","scope":"exterior","value":{"min":4,"max":8.7},"unit":"mbar","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference_range"},{"metric":"exterior_atmosphere_co2_volume_fraction","scope":"exterior","value":95.1,"unit":"% vol","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference"},{"metric":"exterior_mean_temperature","scope":"exterior","value":214,"unit":"K","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference_mean","context":"Promedio global aproximado; no registro por sol ni temperatura del hábitat"},{"metric":"exterior_radiation_absorbed_dose_gcr_rate","scope":"instrument","value":210,"unit":"µGy/day","sourceId":"nasa_mars_rad","evidenceType":"published_observational_approximation","context":"Curiosity RAD, aproximadamente 10 meses de observación desde agosto de 2012; dosis absorbida y NO dosis equivalente"},{"metric":"exterior_atmosphere_o2_volume_fraction","scope":"exterior","value":0.16,"unit":"% vol","sourceId":"nasa_mars_facts","evidenceType":"planetary_reference","context":"Composición media exterior, no oxígeno respirado en traje"},{"metric":"exterior_viking1_diurnal_air_temperature_range","scope":"exterior","value":{"min":184,"max":242},"unit":"K","sourceId":"nasa_mars_facts","evidenceType":"published_reference_range","context":"Ejemplo observado en sitio Viking 1, no todas las ubicaciones ni el aire del traje"},{"metric":"exterior_viking_dust_storm_wind_speed_range","scope":"exterior","value":{"min":17,"max":30},"unit":"m/s","sourceId":"nasa_mars_facts","evidenceType":"published_reference_range","context":"Sitios Viking en tormentas de polvo, no condición constante"}]}'::jsonb);
